  (* [comment removed for export] *)
  Definition WOK (iv : Z * Z) : Prop :=
    (LO' <= fst iv /\ snd iv <= usp0 + -128) \/ (fst iv = RERRNO /\ snd iv = RERRNO + 4)
    \/ (snd iv <= ATOP /\ (snd iv <= 0x10000 \/ 0x59000 <= fst iv))
    \/ (PREAD_STAGE <= fst iv /\ snd iv <= PREAD_STAGE + 65536).

