  Lemma RHEAP_munchW : forall s LB W m m', Forall WOK W -> munch W m m' -> wmono psegs m m' ->
    (forall iv, In iv W -> snd iv <= ATOP -> (snd iv <= 0x10000 \/ 0x59000 <= fst iv) ->
                exists b, In b LB /\ blk_addr b <= fst iv /\ snd iv <= blk_addr b + blk_size b) ->
    RHEAP s LB m -> RHEAP s LB m'.
